const fs = require('fs');
const SEED = 2026;
let s = SEED;
const rnd = () => (s = (s * 1664525 + 1013904223) % 4294967296) / 4294967296;
const pick = a => a[Math.floor(rnd() * a.length)];

const first = ['Aarush','Vihaan','Reyansh','Krish','Ayaan','Kabir','Dhruv','Atharv','Arnav','Neel','Yash','Harsh','Tanmay','Siddharth','Pranav','Nikhil','Rahul','Varun','Manav','Om',
  'Ananya','Diya','Isha','Kavya','Meera','Priya','Riya','Saanvi','Sneha','Tanvi','Aditi','Pooja','Nandini','Shruti','Ritika','Neha','Simran','Aisha','Fatima','Zoya',
  'Gurpreet','Harleen','Lakshmi','Divya','Karthik','Suresh','Arjun','Rohit','Mohit','Vivek','Abhishek','Sanjana','Pallavi','Rashmi','Swati','Tushar','Jayant','Ishaan','Aryan','Ritvik'];
const last = ['Sharma','Verma','Patel','Mehta','Reddy','Nair','Iyer','Menon','Kumar','Singh','Gupta','Joshi','Desai','Kulkarni','Patil','Deshmukh','Bose','Banerjee','Chatterjee','Das',
  'Khan','Ansari','Sheikh','Kapoor','Malhotra','Chopra','Bhatia','Agarwal','Jain','Shah','Rao','Naidu','Pillai','Gowda','Hegde','Thakur','Yadav','Mishra','Tiwari','Pandey'];
const courses = [['B.Tech · CSE',4],['B.Tech · ECE',4],['B.Tech · Mechanical',4],['B.Tech · Civil',4],['B.Sc · Physics',3],['B.Sc · Chemistry',3],['BBA',3],['B.Com',3],['BCA',3],['M.Tech · CSE',2],['MBA',2]];
const messes = ['North Campus Mess','Central Mess','South Campus Mess'];
const hostels = [
  {name:'Maple House', prefix:'A', rooms: 25},
  {name:'Cedar House', prefix:'B', rooms: 25},
  {name:'Oak House',   prefix:'C', rooms: 25}
];
const taken = new Set(['Maple House|A-204','Maple House|A-112','Cedar House|B-306']);
const bedsLeft = {};
const pool = [];
hostels.forEach(h => { for (let i = 0; i < h.rooms; i++) {
  const room = `${h.prefix}-${100 * (1 + Math.floor(i / 9)) + 1 + (i % 9) + 10}`;
  if (!taken.has(h.name + '|' + room)) pool.push({hostel:h.name, room}); } });

const used = new Set(['Aarav Sharma','Rohan Mehta','Aditya Kumar']);
const students = [];
for (let n = 4; n < 104; n++) {
  let name; do { name = pick(first) + ' ' + pick(last); } while (used.has(name)); used.add(name);
  const [course, duration] = pick(courses);
  const studyYear = 1 + Math.floor(rnd() * duration);
  const [fn, ln] = name.toLowerCase().split(' ');
  let allocation = null;
  if (rnd() < 0.88) {
    for (let tries = 0; tries < 200 && !allocation; tries++) {
      const r = pick(pool), k = r.hostel + '|' + r.room;
      if ((bedsLeft[k] ?? 2) > 0) { bedsLeft[k] = (bedsLeft[k] ?? 2) - 1; allocation = {hostel:r.hostel, room:r.room, bed:'0' + (2 - bedsLeft[k])}; }
    }
  }
  students.push({
    id: 'STU-2026-' + String(n).padStart(3, '0'), name, course, studyYear, duration,
    academicYear: '2026–27', email: `${fn}.${ln}${n}@example.edu`,
    phone: '+91 98••• ••' + String(100 + Math.floor(rnd() * 900)),
    guardian: 'Emergency contact on file', mess: pick(messes),
    allocation, marksheet: null, documents: [], history: []
  });
}
fs.writeFileSync('students-data.js',
  '// AUTO-GENERATED by generate-students.js. Synthetic demo data, not real people.\nconst generatedStudents = ' + JSON.stringify(students, null, 1) + ';\n');
const perHostel = {}; students.forEach(x => { if (x.allocation) perHostel[x.allocation.hostel] = (perHostel[x.allocation.hostel] || 0) + 1; });
console.log('Wrote students-data.js:', students.length, 'students');
console.log('Allocated per hostel:', perHostel, '| unallocated:', students.filter(x => !x.allocation).length);
